19	pub fn advance(
20	    body: &Value,
21	    offset: &mut usize,
22	    record_count: usize,
23	    limit: usize,
24	    total_path: Option<&str>,
25	) -> Result<bool, FaucetError> {
26	    // A zero-record page is always the end: the offset would not advance, so
27	    // honouring `total` here would re-issue the identical request forever
28	    // (#78/#6). Stop regardless of what `total_path` reports.
29	    if record_count == 0 {
30	        return Ok(false);
31	    }
32	    *offset += record_count;
33	    if let Some(tp) = total_path {
34	        let results = body
35	            .query(tp)
36	            .map_err(|e| FaucetError::JsonPath(format!("{e}")))?;
37	        if let Some(total_val) = results.first() {
38	            let total = match total_val.as_u64() {
39	                Some(n) => n as usize,
40	                None => {
41	                    tracing::warn!(
42	                        "total_path '{tp}' resolved to non-numeric value {total_val}; \
43	                         falling back to record-count heuristic"
44	                    );
45	                    return Ok(record_count >= limit);
46	                }
47	            };
48	            return Ok(*offset < total);
49	        }
50	    }
51	    Ok(record_count >= limit)
52	}
