147	/// Every node in `sub` must be present (deep-equal) in `sup`. Returns the JSON
148	/// pointer of the first divergence on failure.
149	fn is_subset(sub: &Value, sup: &Value, path: String) -> Result<(), String> {
150	    match (sub, sup) {
151	        (Value::Object(a), Value::Object(b)) => {
152	            for (k, va) in a {
153	                match b.get(k) {
154	                    Some(vb) => is_subset(va, vb, format!("{path}/{k}"))?,
155	                    None => return Err(format!("{path}/{k}")),
156	                }
157	            }
158	            Ok(())
159	        }
160	        (Value::Array(a), Value::Array(b)) => {
161	            // Order-insensitive membership: every element of `sub` must
162	            // deep-equal some element of `sup` (handles connector `oneOf`).
163	            for (i, va) in a.iter().enumerate() {
164	                if !b.iter().any(|vb| vb == va) {
165	                    return Err(format!("{path}/{i}"));
166	                }
167	            }
168	            Ok(())
169	        }
